package preflightapi

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/DeanStr/readyci-cli/pkg/syncbundle"
)

const (
	RunnerEvidenceAttestationSchemaVersion = "readyci.runner_evidence.v1"
	RunnerEvidenceReceiptSchemaVersion     = "readyci.runner_evidence_receipt.v3"
	emptySecretRevisionSetDigest           = "sha256:4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945"
)

// RunnerEvidenceAttestation is generated by the worker holding the active run
// claim. It binds the terminal outcome to the exact execution request the
// worker received. The control plane validates every field against its stored
// run before creating a RunnerEvidenceReceipt.
type RunnerEvidenceAttestation struct {
	SchemaVersion   string `json:"schema_version"`
	RunID           string `json:"run_id"`
	RunGroupID      string `json:"run_group_id"`
	LogicalChildID  string `json:"logical_child_id"`
	Attempt         int    `json:"attempt"`
	WorkspaceDigest string `json:"workspace_digest"`
	ExecutionDigest string `json:"execution_digest"`
	Status          string `json:"status"`
	ExitCode        int    `json:"exit_code"`
}

// RunnerEvidenceReceipt is the durable, service-validated evidence record.
// Artifact fields are added by the control plane after the worker upload has
// completed, so candidate-created files cannot assert their own retention
// binding. Digest is computed over the receipt with Digest cleared.
type RunnerEvidenceReceipt struct {
	SchemaVersion       string                    `json:"schema_version"`
	Attestation         RunnerEvidenceAttestation `json:"attestation"`
	WorkerID            string                    `json:"worker_id"`
	WorkerVersion       string                    `json:"worker_version"`
	WorkerRelease       string                    `json:"worker_release_state"`
	WorkerReleaseDigest string                    `json:"worker_release_digest"`
	ClaimSequence       uint64                    `json:"claim_sequence"`
	ArtifactCount       int                       `json:"artifact_count"`
	ArtifactDigest      string                    `json:"artifact_digest"`
	// ArtifactContentSHA256 binds the exact compressed archive bytes when one
	// artifact archive was retained at completion. It is empty when no archive
	// was uploaded.
	ArtifactContentSHA256 string    `json:"artifact_content_sha256,omitempty"`
	AttestedAt            time.Time `json:"attested_at"`
	Digest                string    `json:"digest"`
}

// RunnerEvidenceEligible reports whether the control plane has enough sealed
// information to validate a worker attestation. Secret-bearing runs must bind
// the server-selected secret revision set without disclosing secret values.
func RunnerEvidenceEligible(spec RunSpec) bool {
	if strings.TrimSpace(spec.RunGroupKind) != "verification_session" ||
		strings.TrimSpace(spec.RunID) == "" ||
		strings.TrimSpace(spec.RunGroupID) == "" ||
		strings.TrimSpace(spec.LogicalChildID) == "" ||
		strings.TrimSpace(spec.WorkerReleaseState) != WorkerReleaseStateProduction ||
		spec.Attempt < 1 {
		return false
	}
	if err := syncbundle.ValidateSnapshotDigest(strings.TrimSpace(spec.SnapshotDigest)); err != nil {
		return false
	}
	if err := syncbundle.ValidateSnapshotDigest(strings.TrimSpace(spec.WorkerReleaseDigest)); err != nil {
		return false
	}
	if spec.SecretsRequested == nil {
		return false
	}
	if !*spec.SecretsRequested {
		return strings.TrimSpace(spec.SecretRevisionDigest) == "" && len(spec.SecretEnv) == 0
	}
	secretRevisionDigest := strings.TrimSpace(spec.SecretRevisionDigest)
	return secretRevisionDigest != emptySecretRevisionSetDigest && syncbundle.ValidateSnapshotDigest(secretRevisionDigest) == nil
}

// RunnerExecutionDigest binds the stable execution request. Ephemeral lease
// material and secret values are intentionally excluded. Secret-bearing runs
// bind the opaque server-selected revision digest instead.
func RunnerExecutionDigest(spec RunSpec) (string, error) {
	environmentRequirements, err := NormalizeEnvironmentRequirements(spec.EnvironmentRequirements)
	if err != nil {
		return "", err
	}
	type execution struct {
		EnvironmentRequirements []string          `json:"environment_requirements,omitempty"`
		RuntimeRequirements     map[string]string `json:"runtime_requirements,omitempty"`
		RunID                   string            `json:"run_id"`
		TeamID                  string            `json:"team_id,omitempty"`
		RunGroupID              string            `json:"run_group_id"`
		RunGroupKey             string            `json:"run_group_key,omitempty"`
		RunGroupKind            string            `json:"run_group_kind"`
		LogicalChildID          string            `json:"logical_child_id"`
		LogicalChildName        string            `json:"logical_child_name,omitempty"`
		MatrixVariant           string            `json:"matrix_variant,omitempty"`
		Attempt                 int               `json:"attempt"`
		ProjectID               string            `json:"project_id"`
		Region                  string            `json:"region"`
		Image                   string            `json:"image"`
		Command                 string            `json:"command"`
		CommandAlias            string            `json:"command_alias,omitempty"`
		Steps                   []RunStepSpec     `json:"steps,omitempty"`
		RunnerSize              string            `json:"runner_size"`
		TimeoutSeconds          int               `json:"timeout_seconds"`
		CacheMode               string            `json:"cache_mode"`
		CacheLaneID             string            `json:"cache_lane_id,omitempty"`
		CacheLaneIndex          *int              `json:"cache_lane_index,omitempty"`
		CacheLaneSizeBytes      int64             `json:"cache_lane_size_bytes,omitempty"`
		ArtifactPaths           []string          `json:"artifact_paths,omitempty"`
		NetworkMode             string            `json:"network_mode"`
		NetworkAllowlist        []string          `json:"network_allowlist,omitempty"`
		Docker                  bool              `json:"docker"`
		Services                []RunServiceSpec  `json:"services,omitempty"`
		WorkerSelector          map[string]string `json:"worker_selector,omitempty"`
		ChangeMode              string            `json:"change_mode"`
		SnapshotDigest          string            `json:"snapshot_digest"`
		ChangedFilesDigest      string            `json:"changed_files_digest"`
		BundleBaselineKey       string            `json:"bundle_baseline_key,omitempty"`
		SecretsRequested        bool              `json:"secrets_requested"`
		SecretRevisionDigest    string            `json:"secret_revision_digest,omitempty"`
		Git                     GitInfo           `json:"git"`
		WorkerReleaseDigest     string            `json:"worker_release_digest"`
	}
	if spec.SecretsRequested == nil {
		return "", fmt.Errorf("runner evidence requires explicit secrets_requested")
	}
	steps := append([]RunStepSpec(nil), spec.Steps...)
	for index := range steps {
		steps[index].Env = cloneRunnerEvidenceStringMap(steps[index].Env)
	}
	services := append([]RunServiceSpec(nil), spec.Services...)
	for index := range services {
		services[index].Env = cloneRunnerEvidenceStringMap(services[index].Env)
		services[index].Ports = append([]string(nil), services[index].Ports...)
		services[index].Logs = append([]string(nil), services[index].Logs...)
	}
	payload := execution{
		EnvironmentRequirements: environmentRequirements,
		RuntimeRequirements:     CloneRuntimeRequirements(spec.RuntimeRequirements),
		RunID:                   strings.TrimSpace(spec.RunID),
		TeamID:                  strings.TrimSpace(spec.TeamID),
		RunGroupID:              strings.TrimSpace(spec.RunGroupID),
		RunGroupKey:             strings.TrimSpace(spec.RunGroupKey),
		RunGroupKind:            strings.TrimSpace(spec.RunGroupKind),
		LogicalChildID:          strings.TrimSpace(spec.LogicalChildID),
		LogicalChildName:        strings.TrimSpace(spec.LogicalChildName),
		MatrixVariant:           strings.TrimSpace(spec.MatrixVariant),
		Attempt:                 spec.Attempt,
		ProjectID:               strings.TrimSpace(spec.ProjectID),
		Region:                  strings.TrimSpace(spec.Region),
		Image:                   strings.TrimSpace(spec.Image),
		Command:                 spec.Command,
		CommandAlias:            strings.TrimSpace(spec.CommandAlias),
		Steps:                   steps,
		RunnerSize:              strings.TrimSpace(spec.RunnerSize),
		TimeoutSeconds:          spec.TimeoutSeconds,
		CacheMode:               strings.TrimSpace(spec.CacheMode),
		CacheLaneID:             strings.TrimSpace(spec.CacheLaneID),
		CacheLaneIndex:          cloneRunnerEvidenceInt(spec.CacheLaneIndex),
		CacheLaneSizeBytes:      spec.CacheLaneSizeBytes,
		ArtifactPaths:           append([]string(nil), spec.ArtifactPaths...),
		NetworkMode:             strings.TrimSpace(spec.NetworkMode),
		NetworkAllowlist:        append([]string(nil), spec.NetworkAllowlist...),
		Docker:                  spec.Docker,
		Services:                services,
		WorkerSelector:          cloneRunnerEvidenceStringMap(spec.WorkerSelector),
		ChangeMode:              strings.TrimSpace(spec.ChangeMode),
		SnapshotDigest:          strings.TrimSpace(spec.SnapshotDigest),
		ChangedFilesDigest:      strings.TrimSpace(spec.ChangedFilesDigest),
		BundleBaselineKey:       strings.TrimSpace(spec.BundleBaselineKey),
		SecretsRequested:        *spec.SecretsRequested,
		SecretRevisionDigest:    strings.TrimSpace(spec.SecretRevisionDigest),
		Git:                     spec.Git,
		WorkerReleaseDigest:     strings.TrimSpace(spec.WorkerReleaseDigest),
	}
	encoded, err := json.Marshal(payload)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(encoded)
	return "sha256:" + hex.EncodeToString(sum[:]), nil
}

func NewRunnerEvidenceAttestation(spec RunSpec, status string, exitCode int) (RunnerEvidenceAttestation, error) {
	if !RunnerEvidenceEligible(spec) {
		return RunnerEvidenceAttestation{}, fmt.Errorf("run is not eligible for runner evidence")
	}
	if !IsTerminalRunStatus(status) || status == StatusUploadExpired {
		return RunnerEvidenceAttestation{}, fmt.Errorf("runner evidence status %q is not a worker terminal outcome", status)
	}
	if exitCode < 0 || exitCode > 255 {
		return RunnerEvidenceAttestation{}, fmt.Errorf("runner evidence exit_code must be between 0 and 255")
	}
	executionDigest, err := RunnerExecutionDigest(spec)
	if err != nil {
		return RunnerEvidenceAttestation{}, err
	}
	return NormalizeRunnerEvidenceAttestation(RunnerEvidenceAttestation{
		SchemaVersion:   RunnerEvidenceAttestationSchemaVersion,
		RunID:           spec.RunID,
		RunGroupID:      spec.RunGroupID,
		LogicalChildID:  spec.LogicalChildID,
		Attempt:         spec.Attempt,
		WorkspaceDigest: spec.SnapshotDigest,
		ExecutionDigest: executionDigest,
		Status:          status,
		ExitCode:        exitCode,
	})
}

func NormalizeRunnerEvidenceAttestation(attestation RunnerEvidenceAttestation) (RunnerEvidenceAttestation, error) {
	attestation.SchemaVersion = strings.TrimSpace(attestation.SchemaVersion)
	attestation.RunID = strings.TrimSpace(attestation.RunID)
	attestation.RunGroupID = strings.TrimSpace(attestation.RunGroupID)
	attestation.LogicalChildID = strings.TrimSpace(attestation.LogicalChildID)
	attestation.WorkspaceDigest = strings.TrimSpace(attestation.WorkspaceDigest)
	attestation.ExecutionDigest = strings.TrimSpace(attestation.ExecutionDigest)
	attestation.Status = strings.TrimSpace(attestation.Status)
	if attestation.SchemaVersion != RunnerEvidenceAttestationSchemaVersion {
		return attestation, fmt.Errorf("unsupported runner evidence schema version %q", attestation.SchemaVersion)
	}
	if attestation.RunID == "" || attestation.RunGroupID == "" || attestation.LogicalChildID == "" {
		return attestation, fmt.Errorf("runner evidence requires run_id, run_group_id, and logical_child_id")
	}
	if attestation.Attempt < 1 {
		return attestation, fmt.Errorf("runner evidence attempt must be positive")
	}
	if err := syncbundle.ValidateSnapshotDigest(attestation.WorkspaceDigest); err != nil {
		return attestation, fmt.Errorf("runner evidence workspace_digest: %w", err)
	}
	if err := syncbundle.ValidateSnapshotDigest(attestation.ExecutionDigest); err != nil {
		return attestation, fmt.Errorf("runner evidence execution_digest: %w", err)
	}
	if !IsTerminalRunStatus(attestation.Status) || attestation.Status == StatusUploadExpired {
		return attestation, fmt.Errorf("runner evidence status %q is not a worker terminal outcome", attestation.Status)
	}
	if attestation.ExitCode < 0 || attestation.ExitCode > 255 {
		return attestation, fmt.Errorf("runner evidence exit_code must be between 0 and 255")
	}
	return attestation, nil
}

func RunnerEvidenceReceiptDigest(receipt RunnerEvidenceReceipt) (string, error) {
	receipt.Digest = ""
	encoded, err := json.Marshal(receipt)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(encoded)
	return "sha256:" + hex.EncodeToString(sum[:]), nil
}

// ValidateRunnerEvidenceReceipt verifies that a receipt has the complete
// service-issued shape and that its digest reproduces from that shape. Verdict
// derivation must use this check rather than trusting a stored boolean flag or
// digest string on its own.
func ValidateRunnerEvidenceReceipt(receipt RunnerEvidenceReceipt) error {
	if receipt.SchemaVersion != strings.TrimSpace(receipt.SchemaVersion) ||
		receipt.SchemaVersion != RunnerEvidenceReceiptSchemaVersion {
		return fmt.Errorf("unsupported runner evidence receipt schema version %q", receipt.SchemaVersion)
	}
	normalizedAttestation, err := NormalizeRunnerEvidenceAttestation(receipt.Attestation)
	if err != nil {
		return fmt.Errorf("runner evidence receipt attestation: %w", err)
	}
	if normalizedAttestation != receipt.Attestation {
		return fmt.Errorf("runner evidence receipt attestation is not normalized")
	}
	if receipt.WorkerID != strings.TrimSpace(receipt.WorkerID) ||
		receipt.WorkerVersion != strings.TrimSpace(receipt.WorkerVersion) ||
		receipt.WorkerID == "" || receipt.WorkerVersion == "" {
		return fmt.Errorf("runner evidence receipt requires worker_id and worker_version")
	}
	if receipt.WorkerRelease != WorkerReleaseStateProduction {
		return fmt.Errorf("runner evidence receipt worker_release_state must be production")
	}
	if err := syncbundle.ValidateSnapshotDigest(receipt.WorkerReleaseDigest); err != nil {
		return fmt.Errorf("runner evidence receipt worker_release_digest: %w", err)
	}
	if receipt.ClaimSequence == 0 {
		return fmt.Errorf("runner evidence receipt claim_sequence must be positive")
	}
	if receipt.ArtifactCount < 0 {
		return fmt.Errorf("runner evidence receipt artifact_count must not be negative")
	}
	if err := syncbundle.ValidateSnapshotDigest(receipt.ArtifactDigest); err != nil {
		return fmt.Errorf("runner evidence receipt artifact_digest: %w", err)
	}
	switch receipt.ArtifactCount {
	case 0:
		if receipt.ArtifactContentSHA256 != "" {
			return fmt.Errorf("runner evidence receipt artifact_content_sha256 must be empty without artifacts")
		}
	case 1:
		if err := ValidateSHA256Hex(receipt.ArtifactContentSHA256); err != nil {
			return fmt.Errorf("runner evidence receipt artifact_content_sha256: %w", err)
		}
	default:
		return fmt.Errorf("runner evidence receipt supports at most one artifact archive")
	}
	if receipt.AttestedAt.IsZero() {
		return fmt.Errorf("runner evidence receipt attested_at is required")
	}
	if receipt.Digest != strings.TrimSpace(receipt.Digest) {
		return fmt.Errorf("runner evidence receipt digest must be normalized")
	}
	if err := syncbundle.ValidateSnapshotDigest(receipt.Digest); err != nil {
		return fmt.Errorf("runner evidence receipt digest: %w", err)
	}
	expected, err := RunnerEvidenceReceiptDigest(receipt)
	if err != nil {
		return fmt.Errorf("digest runner evidence receipt: %w", err)
	}
	if receipt.Digest != expected {
		return fmt.Errorf("runner evidence receipt digest does not match its contents")
	}
	return nil
}

// ValidateSHA256Hex validates the canonical lowercase representation used for
// exact stored-object checksums.
func ValidateSHA256Hex(value string) error {
	if len(value) != sha256.Size*2 {
		return fmt.Errorf("must contain 64 lowercase hexadecimal characters")
	}
	for _, r := range value {
		if r >= '0' && r <= '9' || r >= 'a' && r <= 'f' {
			continue
		}
		return fmt.Errorf("must contain 64 lowercase hexadecimal characters")
	}
	return nil
}

func cloneRunnerEvidenceStringMap(values map[string]string) map[string]string {
	if len(values) == 0 {
		return nil
	}
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	cloned := make(map[string]string, len(values))
	for _, key := range keys {
		cloned[key] = values[key]
	}
	return cloned
}

func cloneRunnerEvidenceInt(value *int) *int {
	if value == nil {
		return nil
	}
	copy := *value
	return &copy
}
